CREATE OR REPLACE FUNCTION public.change_package_price(_package_id uuid, _new_price numeric, _reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.has_role(auth.uid(), 'owner') THEN RAISE EXCEPTION 'Akses ditolak'; END IF; IF _new_price < 0 OR length(trim(_reason)) = 0 THEN RAISE EXCEPTION 'Harga dan alasan wajib diisi'; END IF; PERFORM set_config('app.price_reason', _reason, true); UPDATE public.packages SET price = _new_price WHERE id = _package_id; IF NOT FOUND THEN RAISE EXCEPTION 'Paket tidak ditemukan'; END IF; END $$;
REVOKE ALL ON FUNCTION public.change_package_price(uuid, numeric, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.change_package_price(uuid, numeric, text) TO authenticated;
CREATE OR REPLACE FUNCTION public.advance_room_cleaning(_room_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT (public.has_role(auth.uid(), 'owner') OR (public.has_role(auth.uid(), 'employee') AND EXISTS (SELECT 1 FROM public.employees WHERE user_id = auth.uid() AND active AND position = 'housekeeping'))) THEN RAISE EXCEPTION 'Akses ditolak'; END IF; UPDATE public.rooms SET status = CASE WHEN status = 'dirty' THEN 'cleaning'::public.room_status ELSE 'ready'::public.room_status END WHERE id = _room_id AND status IN ('dirty', 'cleaning'); IF NOT FOUND THEN RAISE EXCEPTION 'Status kamar tidak dapat diubah'; END IF; END $$;
REVOKE ALL ON FUNCTION public.advance_room_cleaning(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.advance_room_cleaning(uuid) TO authenticated;